import 'package:flutter/material.dart';
import '../../core/app_theme.dart';
import '../../data/repositories/patient_portal_repository.dart';
import '../../shared/widgets/ui.dart';

class RecordsScreen extends StatelessWidget {
  const RecordsScreen({super.key});
  final _upper = const [18,17,16,15,14,13,12,11,21,22,23,24,25,26,27,28];
  final _lower = const [48,47,46,45,44,43,42,41,31,32,33,34,35,36,37,38];
  @override Widget build(BuildContext context) {
    final repo=PatientPortalRepository();
    return DefaultTabController(length:4,child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[
      const Padding(padding:EdgeInsets.fromLTRB(18,20,18,0),child:PageHeading('My dental records',subtitle:'Read-only information shared by your dental care team.')),
      const Padding(padding:EdgeInsets.fromLTRB(18,12,18,0),child:SurfaceCard(color:AppColors.sky,child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Icon(Icons.verified_user_outlined,color:AppColors.deepTeal),SizedBox(width:10),Expanded(child:Text('Official patient records are maintained by authorized clinic staff. If something looks incorrect, contact the clinic.',style:TextStyle(fontSize:11,height:1.5)))]))),
      Padding(padding:const EdgeInsets.fromLTRB(18,14,18,10),child:Container(decoration:BoxDecoration(color:Theme.of(context).cardColor,borderRadius:BorderRadius.circular(14)),child:const TabBar(isScrollable:true,tabAlignment:TabAlignment.start,labelColor:AppColors.deepTeal,unselectedLabelColor:AppColors.muted,indicatorColor:AppColors.teal,tabs:[Tab(text:'Overview'),Tab(text:'Dental chart'),Tab(text:'History'),Tab(text:'Files')]))),
      Expanded(child:TabBarView(children:[
        _Overview(repo:repo),_Chart(repo:repo,upper:_upper,lower:_lower),_History(repo:repo),_Files(repo:repo),
      ])),
    ]));
  }
}

class _Overview extends StatelessWidget { const _Overview({required this.repo}); final PatientPortalRepository repo; @override Widget build(BuildContext c)=>ListView(padding:EdgeInsets.zero,children:[
  StreamBuilder<Map<String,dynamic>?>(stream:repo.watchMyPatientProfile(),builder:(c,s){final p=s.data??{};return _RecordCard(title:'Medical information',icon:Icons.health_and_safety_outlined,child:s.hasError?Text('Could not load profile: ${s.error}'):Column(children:[_row('Patient ID',(p['id']??'Not linked').toString()),_row('Known allergies',(p['allergies']??'Not recorded').toString()),_row('Medical notes',(p['medical_notes']??p['medicalNotes']??'Not recorded').toString()),_row('Blood type',(p['blood_type']??p['bloodType']??'Not recorded').toString())]));}),
  StreamBuilder<List<Map<String,dynamic>>>(stream:repo.watchMyAppointments(),builder:(c,s)=>_RecordCard(title:'Recent appointments',icon:Icons.calendar_month_outlined,child:s.hasError?Text('Could not load appointments: ${s.error}'):!s.hasData?const Center(child:CircularProgressIndicator()):s.data!.isEmpty?const _Empty('No appointment history is available yet.'):Column(children:s.data!.map((a)=>_row((a['service']??'Dental visit').toString(),'${a['date']??''} · ${a['status']??''}')).toList()))),
]); }
class _Chart extends StatelessWidget {const _Chart({required this.repo,required this.upper,required this.lower});final PatientPortalRepository repo;final List<int> upper,lower;@override Widget build(BuildContext c)=>StreamBuilder<Map<String,dynamic>?>(stream:repo.watchMyDentalChart(),builder:(c,s){final chart=s.data??{};final teeth=chart['teeth'] is Map?Map<String,dynamic>.from(chart['teeth'] as Map):chart;return ListView(padding:EdgeInsets.zero,children:[_RecordCard(title:'Dental chart',icon:Icons.grid_view_rounded,child:s.hasError?Text('Could not load dental chart: ${s.error}'):!s.hasData?const Center(child:CircularProgressIndicator()):teeth.isEmpty?const _Empty('Your dentist has not shared a dental chart yet.'):Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('UPPER JAW',style:TextStyle(fontWeight:FontWeight.w800,fontSize:10,color:AppColors.muted)),const SizedBox(height:8),_teeth(upper,teeth),const Divider(height:20),const Text('LOWER JAW',style:TextStyle(fontWeight:FontWeight.w800,fontSize:10,color:AppColors.muted)),const SizedBox(height:8),_teeth(lower,teeth)]))]);});}
Widget _teeth(List<int> ids,Map<String,dynamic> chart)=>Wrap(spacing:5,runSpacing:6,children:ids.map((id){final v=chart['$id']??chart[id.toString()];return Container(width:37,padding:const EdgeInsets.symmetric(vertical:7),decoration:BoxDecoration(color:v==null?Colors.grey.shade100:AppColors.mint,borderRadius:BorderRadius.circular(8),border:Border.all(color:AppColors.line)),child:Column(children:[Text('$id',style:const TextStyle(fontSize:9,fontWeight:FontWeight.w700)),Text(v?.toString()??'—',maxLines:1,overflow:TextOverflow.ellipsis,style:const TextStyle(fontSize:7,color:AppColors.muted))]));}).toList());
class _History extends StatelessWidget {const _History({required this.repo});final PatientPortalRepository repo;@override Widget build(BuildContext c)=>StreamBuilder<List<Map<String,dynamic>>>(stream:repo.watchMyDentalChartHistory(),builder:(c,s)=>ListView(padding:EdgeInsets.zero,children:[_RecordCard(title:'Dental history',icon:Icons.history_rounded,child:s.hasError?Text('Could not load dental history: ${s.error}'):!s.hasData?const Center(child:CircularProgressIndicator()):s.data!.isEmpty?const _Empty('No dental chart history has been shared yet.'):Column(children:s.data!.map((h)=>_row((h['tooth']??h['toothNumber']??'Clinical entry').toString(),'${h['date']??''} · ${h['condition']??h['diagnosis']??''}')).toList()))]));}
class _Files extends StatelessWidget {const _Files({required this.repo});final PatientPortalRepository repo;@override Widget build(BuildContext c)=>StreamBuilder<List<Map<String,dynamic>>>(stream:repo.watchMyFiles(),builder:(c,s)=>ListView(padding:EdgeInsets.zero,children:[_RecordCard(title:'Files shared by the clinic',icon:Icons.folder_open_outlined,child:s.hasError?Text('Could not load files: ${s.error}'):!s.hasData?const Center(child:CircularProgressIndicator()):s.data!.isEmpty?const _Empty('There are no files attached to your patient record yet.'):Column(children:s.data!.map((f)=>ListTile(contentPadding:EdgeInsets.zero,leading:const Icon(Icons.insert_drive_file_outlined,color:AppColors.teal),title:Text((f['name']??f['fileName']??'Patient file').toString()),subtitle:Text((f['createdAt']??f['date']??'').toString()),onTap:(){final url=(f['url']??'').toString();if(url.isNotEmpty)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Open files through the clinic-provided secure file link.'))); } )).toList()))]));}
class _RecordCard extends StatelessWidget {const _RecordCard({required this.title,required this.icon,required this.child});final String title;final IconData icon;final Widget child;@override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.fromLTRB(18,8,18,4),child:SurfaceCard(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Icon(icon,color:AppColors.teal),const SizedBox(width:9),Text(title,style:const TextStyle(fontWeight:FontWeight.w800))]),const SizedBox(height:14),child])));}
Widget _row(String a,String b)=>Padding(padding:const EdgeInsets.symmetric(vertical:6),child:Row(crossAxisAlignment:CrossAxisAlignment.start,children:[Expanded(child:Text(a,style:const TextStyle(fontSize:10,color:AppColors.muted))),const SizedBox(width:8),Expanded(child:Text(b,style:const TextStyle(fontSize:10,fontWeight:FontWeight.w600),textAlign:TextAlign.end))]));
class _Empty extends StatelessWidget {const _Empty(this.text);final String text;@override Widget build(BuildContext c)=>Container(padding:const EdgeInsets.all(13),decoration:BoxDecoration(color:Theme.of(c).scaffoldBackgroundColor,borderRadius:BorderRadius.circular(10)),child:Text(text,style:const TextStyle(fontSize:11,color:AppColors.muted)));}
